#!/bin/bash
# ncu on the OptiX only builds (no TTU code of ours), RTX 4090 tethys GPU 1. Predictions: model/predictions_4090_batch6.md (commit 25789e1, before any run).
# usage: ncu_4090_batch6.sh NAME -- command...   (run in the program's directory). Raw csv to notes/ncu4090/ncu_NAME_<ts>.csv (noclobber); SM clock sampled beside it.
set -C; source ~/cuda128.sh; export LD_LIBRARY_PATH=$HOME/opt/nvoptix-580.178.04:$LD_LIBRARY_PATH CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=1 TTU_GPU=1 RTNN_DRAM_GB=11.5958 TMPDIR=$HOME/ncutmp
M=gpu__time_duration.sum,launch__grid_size,lts__t_bytes.sum,dram__bytes.sum,smsp__inst_executed.sum,lts__t_sector_hit_rate.pct,lts__throughput.avg.pct_of_peak_sustained_elapsed,l1tex__throughput.avg.pct_of_peak_sustained_elapsed,dram__throughput.avg.pct_of_peak_sustained_elapsed,sm__throughput.avg.pct_of_peak_sustained_elapsed,smsp__average_warps_issue_stalled_long_scoreboard_per_issue_active.ratio,smsp__average_warps_issue_stalled_lg_throttle_per_issue_active.ratio,smsp__average_warps_issue_stalled_drain_per_issue_active.ratio,smsp__average_warps_issue_stalled_no_instruction_per_issue_active.ratio,smsp__average_warps_issue_stalled_short_scoreboard_per_issue_active.ratio,smsp__average_warps_issue_stalled_wait_per_issue_active.ratio,smsp__average_warps_issue_stalled_math_pipe_throttle_per_issue_active.ratio,smsp__average_warps_issue_stalled_membar_per_issue_active.ratio,smsp__average_warps_issue_stalled_not_selected_per_issue_active.ratio,smsp__average_warps_issue_stalled_selected_per_issue_active.ratio,smsp__average_warps_issue_stalled_barrier_per_issue_active.ratio,smsp__average_warps_issue_stalled_lg_throttle_per_issue_active.ratio,sm__cycles_elapsed.avg.per_second
n=$1; shift 2; ts=$(date +%Y%m%dT%H%M%S); out=$HOME/eoss/notes/ncu4090/ncu_${n}_$ts.csv
[ -z "$(nvidia-smi -i 1 --query-compute-apps=pid --format=csv,noheader)" ] && [ "$(nvidia-smi -i 1 --query-gpu=utilization.gpu --format=csv,noheader,nounits)" -lt 10 ] || { echo "GPU 1 busy, stop"; exit 3; }
nvidia-smi -i 1 --query-gpu=timestamp,clocks.sm --format=csv,noheader -lms 50 > ${out%.csv}.clk & sp=$!
timeout -k 2 240 ncu --csv --clock-control none --cache-control none --metrics $M "$@" > $out 2> $out.err; rc=$?; kill $sp; wait $sp 2>/dev/null
echo "$n rc $rc $out"; exit $rc
